steps=[('fmt',['cargo','fmt','--all','--check']),('validation-python',['python3','scripts/test-validation-import.py']),('frontend-python',['python3','-I','scripts/test-frontend-campaign.py']),('parity-ledger',['python3','-I','scripts/check-parity-ledger.py']),('parity-ledger-tests',['python3','-I','scripts/test-parity-ledger.py']),('clippy',['cargo','clippy','--workspace','--all-targets','--locked','--','-D','warnings']),('nextest',['cargo','nextest','run','--workspace','--locked','--profile','ci','--test-threads','2']),('doctests',['cargo','test','--workspace','--doc','--locked']),('rustdoc',['cargo','doc','--workspace','--no-deps','--locked']),('layering',['cargo','xtask','check-layering']),('trace-standalone',['cargo','build','-p','dive-trace','--locked']),('deny',['cargo','deny','--locked','check'])]
